package com.fitnessapp.feature.splash

import androidx.compose.foundation.Canvas
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke

/**
 * The segmented ring of the logo, drawn from [RingSpec] (measured from the reference logo and
 * generated by design/generate_logo.py).
 *
 * [fill] 0..1 sweeps clockwise from the first arc to the last one: every solid arc starts as a dim
 * track and fills with its own colour as the sweep reaches it. At 1 the ring is identical to the
 * static logo (the thin dashes are always dim: they are the part of the ring left unfilled).
 *
 * The canvas must be square and use the same box as the figure drawable, because both are
 * laid out in the logo's 1040 x 1040 space.
 */
@Composable
fun ProgressRing(fill: Float, modifier: Modifier = Modifier) {
    Canvas(modifier = modifier) {
        val unit = size.minDimension / RingSpec.LOGO_SIZE
        val swept = fill.coerceIn(0f, 1f) * (RingSpec.SWEEP_END_DEG - RingSpec.SWEEP_START_DEG)

        for (dash in RingSpec.dashes) {
            drawBand(dash.startDeg, dash.endDeg - dash.startDeg, RingSpec.DASH_INNER, RingSpec.DASH_OUTER, unit, RingSpec.DashColor)
        }
        for (arc in RingSpec.arcs) {
            drawBand(arc.startDeg, arc.lengthDeg, RingSpec.ARC_INNER, RingSpec.ARC_OUTER, unit, RingSpec.TrackColor)
            val filled = (swept - (arc.startDeg - RingSpec.SWEEP_START_DEG)).coerceIn(0f, arc.lengthDeg)
            if (filled > 0f) {
                drawBand(arc.startDeg, filled, RingSpec.ARC_INNER, RingSpec.ARC_OUTER, unit, arc.color)
            }
        }
    }
}

/** An annular sector with radial ends. A butt-capped arc stroke has exactly that shape. */
private fun DrawScope.drawBand(startDeg: Float, sweepDeg: Float, inner: Float, outer: Float, unit: Float, color: Color) {
    val mid = (inner + outer) / 2f * unit
    drawArc(
        color = color,
        startAngle = startDeg,
        sweepAngle = sweepDeg,
        useCenter = false,
        topLeft = Offset(center.x - mid, center.y - mid),
        size = Size(mid * 2, mid * 2),
        style = Stroke(width = (outer - inner) * unit),
    )
}
